    hints *storage.SelectHints, matchers ...*labels.Matcher) storage.SeriesSet { ... }
```
**Required addition:**
```go
func (q *querier) SelectSorted(ctx context.Context,
    hints *storage.SelectHints, matchers ...*labels.Matcher) storage.SeriesSet {
    return q.Select(ctx, true, hints, matchers...)
}
```

#### `web/api/testhelpers/mocks.go` — `FakeQuerier`
```go
func (f *FakeQuerier) Select(_ context.Context, _ bool,
    _ *storage.SelectHints, _ ...*labels.Matcher) storage.SeriesSet {
    return &FakeSeriesSet{series: f.series, idx: -1}
}
```
**Required addition:**
```go
